insert into problemas (id, cultivo_id, tipo, nombre, descripcion, orden, fuente, fotos) values
  (1, 'pitahaya', 'plaga', 'Avispas / murujas', 'Raspan botones florales, flores y frutos.', 1, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb),
