  (7, 'pitahaya', 'plaga', 'Nematodos', 'Raíces con nudos o lesiones; planta débil.', 7, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb),
  (8, 'pitahaya', 'enfermedad', 'Antracnosis (Colletotrichum) y Alternaria', 'Manchas hundidas en cladodios, flores y frutos.', 8, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb),
  (9, 'pitahaya', 'enfermedad', 'Fusarium / sarna fúngica', 'Pudrición de flor, manchado y sarna en fruto; pudrición de tallo.', 9, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb),
  (10, 'pitahaya', 'enfermedad', 'Prevención de hongos (amplio espectro)', 'Aplicaciones preventivas, sobre todo en épocas de lluvia.', 10, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb),
  (11, 'pitahaya', 'enfermedad', 'Bacteriosis / pudrición blanda', 'Tejido acuoso, blando y con mal olor.', 11, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb),
  (12, 'pitahaya', 'enfermedad', 'Hongos del suelo (desinfección)', 'Antes de sembrar o en focos de pudrición de raíz.', 12, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb),
  (13, 'pitahaya', 'maleza', 'Malezas en general (no selectivo)', 'Control total de malezas en calles. No tocar la planta.', 13, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb),
  (14, 'pitahaya', 'maleza', 'Malezas de hoja ancha', 'Herbicida selectivo para hoja ancha.', 14, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb),
