  (16, 'pitahaya', 'nutricion', 'Enraizamiento', 'Esquejes nuevos o raíces débiles.', 16, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb),
  (17, 'pitahaya', 'nutricion', 'Brotación y floración pareja', 'Estimular y emparejar la brotación y la floración.', 17, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb),
  (18, 'pitahaya', 'nutricion', 'Estrés de la planta', 'Después de sequía, exceso de lluvia, plagas o podas.', 18, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb),
  (19, 'pitahaya', 'nutricion', 'Engrose de fruto', 'Mejorar tamaño y llenado del fruto.', 19, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb),
  (20, 'pitahaya', 'nutricion', 'Suelo ácido (pH bajo)', 'Corregir acidez y aportar calcio y magnesio.', 20, 'Lista de productos EQ para pitahaya (Excel del asesor)', '[]'::jsonb),
  (21, 'cacao', 'enfermedad', 'Monilia (Moniliophthora roreri)', 'Manchas y bultos en mazorcas jóvenes, luego polvo blanco-crema. Retirar mazorcas enfermas cada semana.', 21, 'Manuales de cacao (ICA Colombia, CATIE, guía PNUD Ecuador) y fichas técnicas; revisar', '[]'::jsonb),
  (22, 'cacao', 'enfermedad', 'Escoba de bruja (Moniliophthora perniciosa)', 'Brotes hinchados en forma de escoba y mazorcas deformes. Poda sanitaria y sacar el material enfermo del lote.', 22, 'Manuales de cacao (ICA Colombia, CATIE, guía PNUD Ecuador) y fichas técnicas; revisar', '[]'::jsonb),
  (23, 'cacao', 'enfermedad', 'Mazorca negra (Phytophthora)', 'Manchas café-negras en la mazorca que avanzan rápido con la lluvia. Mejorar drenaje y regular sombra.', 23, 'Manuales de cacao (ICA Colombia, CATIE, guía PNUD Ecuador) y fichas técnicas; revisar', '[]'::jsonb),
  (24, 'cacao', 'plaga', 'Chinche del cacao (Monalonion)', 'Manchas negras hundidas en mazorcas y brotes por picaduras.', 24, 'Manuales de cacao (ICA Colombia, CATIE, guía PNUD Ecuador) y fichas técnicas; revisar', '[]'::jsonb),
  (25, 'cacao', 'plaga', 'Hormigas y comejenes', 'Daño en raíces, brotes y cortes de hojas.', 25, 'Manuales de cacao (ICA Colombia, CATIE, guía PNUD Ecuador) y fichas técnicas; revisar', '[]'::jsonb),
  (26, 'cacao', 'maleza', 'Malezas en general (no selectivo)', 'Control en calles sin tocar el tronco ni las hojas del cacao.', 26, 'Manuales de cacao (ICA Colombia, CATIE, guía PNUD Ecuador) y fichas técnicas; revisar', '[]'::jsonb),
  (27, 'cacao', 'nutricion', 'Suelo ácido (pH bajo)', 'Corregir acidez y aportar calcio y magnesio.', 27, 'Manuales de cacao (ICA Colombia, CATIE, guía PNUD Ecuador) y fichas técnicas; revisar', '[]'::jsonb),
  (28, 'cacao', 'nutricion', 'Floración y cuajado', 'Apoyar floración y cuajado de mazorcas.', 28, 'Manuales de cacao (ICA Colombia, CATIE, guía PNUD Ecuador) y fichas técnicas; revisar', '[]'::jsonb);
